  {"prompt": "Συνώνυμο/ορισμός: με πολύ μεγάλη κλίση", "options": [], "answer": "απότομων", "answer_note": "απότομος = steep; genitive plural with «βράχων»."},
  {"prompt": "Συνώνυμο/ορισμός: έβαζαν στον τάφο", "options": [], "answer": "έθαβαν", "answer_note": "θάβω = to bury; imperfect έθαβαν."},
  {"prompt": "Συνώνυμο/ορισμός: όσοι κάνουν μεγάλους περιπάτους στη φύση", "options": [], "answer": "πεζοπόροι", "answer_note": "ο πεζοπόρος = hiker."},
  {"prompt": "Συνώνυμο/ορισμός: περνούν από τη μία άκρη ως την άλλη", "options": [], "answer": "διασχίζουν", "answer_note": "διασχίζω = to cross, traverse."},
